script:
'use strict';
const BASE = 'https://e-hentai.org';
const MAX_GALLERY_PAGES = 100, MAX_IMAGES = 5000;
const cursors = new Map();
function fail(message) { throw new Error('E-Hentai：' + message); }
function pageNumber(page) { if (!Number.isInteger(page) || page < 1) fail('页码无效'); return page; }
function absolute(value) {
  value = String(value || '').trim();
  if (value.startsWith('//')) return 'https:' + value;
  if (value.startsWith('/')) return BASE + value;
  if (/^https:\/\//.test(value)) return value;
  fail('地址不是受支持的 HTTPS 地址');
}
function gallery(value) {
  const url = absolute(value), match = /^https:\/\/e-hentai\.org\/g\/([1-9][0-9]*)\/([a-f0-9]{10})\/?(?:\?p=([0-9]+))?$/.exec(url);
  if (!match) fail('图库地址无效；仅支持 E-Hentai，不支持 ExHentai');
  return {id: match[1], token: match[2], page: Number(match[3] || 0),
    url: BASE + '/g/' + match[1] + '/' + match[2] + '/', identity: match[1] + '/' + match[2]};
}
function image(value) {
  const url = absolute(value);
  if (!/^https:\/\/[^\s"'<>\\@]+$/.test(url)) fail('图片地址无效');
  return url;
}
async function fetchHtml(url) {
  // All metadata/page traversal stays on the public site; never follow a
  // discovered ExHentai/login/archive/donation URL or execute site JavaScript.
  if (!/^https:\/\/e-hentai\.org(?:\/|$)/.test(url)) fail('请求不属于 E-Hentai 公开站点');
  const response = await triomi.fetch(url, {headers: {'Referer': BASE + '/', 'User-Agent': 'Mozilla/5.0'}});
  if (response.status !== 200) fail('HTTP ' + response.status + '，内容可能受限、已删除或请求过于频繁');
  if (response.url && !/^https:\/\/e-hentai\.org(?:\/|$)/.test(response.url)) fail('站点重定向到公开访问范围之外');
  if (response.body.length > 2000000) fail('网页超过安全限制');
  const rendered = response.body.replace(/<(script|style)\b[^>]*>[\s\S]*?<\/\1\s*>/gi, '');
  const title = await triomi.value(rendered, 'title', 'text') || '';
  if (/Just a moment|Attention Required|verify.*human/i.test(title) ||
      await triomi.value(rendered, '#challenge-form, #challenge-running', 'id')) fail('站点要求验证，不绕过验证');
  const warning = (await triomi.value(rendered, '.searchwarn, #messagebox, .d', 'text') || '').trim();
  if (/temporarily banned|exceeded.*(?:quota|limit)|image viewing limit/i.test(warning)) fail('访问暂时受限或额度已用尽');
  return response.body;
}
async function listing(url) {
  const doc = await fetchHtml(url);
  const rows = await triomi.select(doc, '.itg > tbody > tr, .itg > .gl1t', {
    href: {selector: '.glname a[href], .gl3c > a[href], .gl2e > div > a[href], a[href*="/g/"]', attr: 'href'},
    title: '.glink', imageTitle: {selector: 'img', attr: 'title'},
    src: {selector: '.glthumb img, .gl1e img, .gl3t img, img', attr: 'src'},
    lazy: {selector: '.glthumb img, .gl1e img, .gl3t img, img', attr: 'data-src'}
  });
  const result = [], seen = new Set();
  for (const row of rows) {
    if (!row.href) continue; // Header / advertisement rows.
    const ref = gallery(row.href);
    if (seen.has(ref.identity)) continue;
    const title = row.title || row.imageTitle;
    if (!title) fail('图库列表标题缺失');
    seen.add(ref.identity);
    const cover = row.lazy || row.src;
    result.push({remoteId: ref.identity, type: 'manga', title: title,
      url: ref.url, coverUrl: cover && !/^data:/i.test(cover) ? image(cover) : null});
  }
  if (!result.length) {
    const text = await triomi.value(doc, 'body', 'text') || '';
    if (!/No hits found|No galleries found|No unfiltered results/i.test(text)) {
      fail('图库列表为空或网页格式变化，可能需要网站登录');
    }
  }
  const links = await triomi.values(doc, '.searchnav a[href], a#unext[href]', 'href');
  let next = null;
  for (const link of links) {
    // Site jump controls are inert actions, not page URLs. Never evaluate them.
    if (/^javascript:/i.test(String(link).trim())) continue;
    const candidate = absolute(link);
    const match = /^https:\/\/e-hentai\.org\/\?([^#]*)$/.exec(candidate);
    if (!match) continue;
    const cursor = /(?:^|&)next=([1-9][0-9]*)(?:&|$)/.exec(match[1]);
    if (!cursor) continue;
    if (next && next !== cursor[1]) fail('列表游标不一致');
    next = cursor[1];
  }
  return {items: result, next: next};
}
async function cursorList(query, page) {
  pageNumber(page);
  // Parse the returned layout; inline_set changes a site preference and returns 302.
  const first = BASE + '/' + (query ? '?f_search=' + encodeURIComponent(query) : '');
  let state = cursors.get(first);
  if (page === 1 || !state) {
    state = {urls: [first], end: null};
    cursors.delete(first); cursors.set(first, state);
    if (cursors.size > 8) cursors.delete(cursors.keys().next().value);
  }
  if (state.end !== null && page > state.end) return [];
  if (page - state.urls.length > 20) fail('跳页跨度过大，请从第一页顺序浏览');
  while (state.urls.length < page) {
    const previous = await listing(state.urls[state.urls.length - 1]);
    if (!previous.next) { state.end = state.urls.length; return []; }
    const url = first + (query ? '&next=' : '?next=') + previous.next;
    if (state.urls.indexOf(url) >= 0) fail('列表游标重复，请刷新');
    state.urls.push(url);
  }
  const result = await listing(state.urls[page - 1]);
  if (result.next) {
    const next = first + (query ? '&next=' : '?next=') + result.next;
    if (state.urls.slice(0, page).indexOf(next) >= 0) fail('列表游标循环，请刷新');
    state.urls[page] = next;
  } else state.end = page;
  return result.items;
}
async function discover(url, page) {
  pageNumber(page);
  if (url === BASE + '/popular') return page === 1 ? (await listing(url)).items : [];
  return cursorList('', page);
}
async function search(keyword, page) {
  pageNumber(page);
  const query = String(keyword || '').trim();
  if (/^https?:\/\//.test(query)) {
    const ref = gallery(query);
    return page === 1 ? [(await galleryDetails(ref.url)).item] : [];
  }
  return cursorList(query, page);
}
async function galleryDetails(url) {
  const ref = gallery(url), doc = await fetchHtml(ref.url);
  const title = await triomi.value(doc, '#gn', 'text') || await triomi.value(doc, '#gj', 'text');
  if (!title) fail('图库不可用、已删除或需要网站登录');
  const rows = await triomi.select(doc, '#gdd tr', {
    label: '.gdt1', value: '.gdt2', href: {selector: '.gdt2 a[href]', attr: 'href'}
  });
  const metadata = {};
  for (const row of rows) metadata[row.label.replace(/:$/, '').trim().toLowerCase()] = row;
  const tagRows = await triomi.select(doc, '#taglist tr', {namespace: '.tc', html: {selector: '.', attr: 'html'}});
  const tags = [];
  for (const row of tagRows) {
    const ns = row.namespace.replace(/:$/, '').trim();
    for (const tag of await triomi.values(row.html, 'div[id^="td_"] a, div.gt a, div.gtl a, div.gtw a', 'text')) {
      if (tag) tags.push((ns ? ns + ':' : '') + tag);
    }
  }
  const coverStyle = await triomi.value(doc, '#gd1 > div', 'style') || '';
  const match = /url\(\s*["']?([^"')]+)["']?\s*\)/.exec(coverStyle);
  const rating = Number((await triomi.value(doc, '#rating_label', 'text') || '').replace(/^Average:\s*/i, ''));
  const artist = tags.filter(t => /^artist:/.test(t)).map(t => t.slice(7)).join(' / ');
  const item = {remoteId: ref.identity, type: 'manga', title: title, url: ref.url,
    coverUrl: match ? image(match[1]) : null, author: artist || await triomi.value(doc, '#gdn a', 'text') || '',
    description: ['Japanese title: ' + (await triomi.value(doc, '#gj', 'text') || ''),
      ...rows.filter(r => r.value).map(r => r.label + ' ' + r.value)].join('\n'),
    tags: Array.from(new Set(tags)), rating: Number.isFinite(rating) && rating > 0 ? rating : null};
  const parent = metadata.parent && metadata.parent.href ? gallery(metadata.parent.href).url : null;
  const posted = metadata.posted && metadata.posted.value;
  const versions = await triomi.select(doc, '#gnd a[href]', {href: {selector: '.', attr: 'href'}, title: '.'});
  return {item: item, parent: parent, posted: posted, versions: versions};
}
async function detail(url) {
  const selected = await galleryDetails(url), visited = new Set([selected.item.url]);
  let root = selected;
  for (let depth = 0; root.parent; depth++) {
    if (depth >= 10 || visited.has(root.parent)) fail('图库版本链过长或存在循环');
    visited.add(root.parent); root = await galleryDetails(root.parent);
  }
  const versions = [{url: root.item.url, title: root.item.title, posted: root.posted}];
  const seen = new Set([root.item.url]);
  for (const entry of root.versions) {
    const ref = gallery(entry.href);
    if (seen.has(ref.url)) continue;
    seen.add(ref.url); versions.push({url: ref.url, title: entry.title || ref.identity});
  }
  if (!seen.has(selected.item.url)) versions.push({url: selected.item.url, title: selected.item.title, posted: selected.posted});
  if (versions.length > 100) fail('图库版本数量超过安全限制');
  return {item: selected.item, chapters: versions.map((version, index) => ({
    remoteId: gallery(version.url).identity, title: 'v' + (index + 1) + ': ' + version.title,
    url: version.url, number: index + 1, sortIndex: index,
    releaseDate: version.posted && /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}$/.test(version.posted) ? version.posted.replace(' ', 'T') + ':00Z' : null
  }))};
}
async function content(url) {
  const ref = gallery(url), seen = new Set(), pages = new Map();
  let total = null;
  for (let index = 0; ; index++) {
    if (index >= MAX_GALLERY_PAGES) fail('缩略图分页超过安全限制');
    const doc = await fetchHtml(ref.url + (index ? '?p=' + index : ''));
    if (!await triomi.value(doc, '#gn, #gj', 'text')) fail('图库不可用或需要网站登录');
    const lengths = await triomi.select(doc, '#gdd tr', {label: '.gdt1', value: '.gdt2'});
    const length = lengths.find(r => /^Length:\s*$/i.test(r.label));
    if (!length || !/^\d+ pages?$/.test(length.value)) fail('图库页数缺失，不能保证完整阅读');
    const count = Number(length.value.match(/^\d+/)[0]);
    if (count < 1 || count > MAX_IMAGES || total !== null && count !== total) fail('图库页数无效或发生变化，请重载');
    total = count;
    const links = await triomi.values(doc, '#gdt a[href], .gdtm a[href]', 'href');
    if (!links.length) fail('公开图片页面列表为空');
    for (const link of links) {
      const pageUrl = absolute(link), match = /^https:\/\/e-hentai\.org\/s\/([a-f0-9]+)\/([1-9][0-9]*)-([1-9][0-9]*)$/.exec(pageUrl);
      if (!match || match[2] !== ref.id) fail('图片页图库身份不匹配');
      const number = Number(match[3]);
      if (number > total || pages.has(number) && pages.get(number) !== pageUrl || seen.has(pageUrl)) fail('图片页重复或编号无效');
      pages.set(number, pageUrl); seen.add(pageUrl);
    }
    const nav = await triomi.select(doc, 'table.ptt a[href]', {href: {selector: '.', attr: 'href'}, title: '.'});
    const next = nav.find(r => /^(?:>|›|»)$/.test(r.title.trim()));
    if (!next) break;
    const nextRef = gallery(next.href);
    if (nextRef.identity !== ref.identity || nextRef.page !== index + 1) fail('缩略图下一页身份或页码无效');
  }
  if (pages.size !== total) fail('图片页列表不完整，请重载');
  const images = [];
  for (let index = 1; index <= total; index++) {
    if (!pages.has(index)) fail('图片页编号不连续');
    images.push(pages.get(index));
  }
  return {images: images, imageHeaders: {'Referer': BASE + '/', 'User-Agent': 'Mozilla/5.0'}};
}
